// Render a few individual frames to build/preview/*.png for inspection.
'use strict';
const fs = require('fs'), path = require('path'), os = require('os');
const { serve, launchChrome, CDP, sleep, ROOT } = require('./cdp');

(async () => {
  const frames = (process.argv[2] || '0').split(',').map(Number);
  const outDir = path.join(ROOT, 'build', 'preview');
  fs.mkdirSync(outDir, { recursive: true });
  const port = 8111;
  const srv = await serve(port);
  const prof = fs.mkdtempSync(path.join(os.tmpdir(), 'cr-'));
  const { proc, wsUrl } = await launchChrome(9333, `http://127.0.0.1:${port}/index.html`, prof);
  const cdp = await CDP.connect(wsUrl);
  for (let k = 0; k < 400; k++) {
    const e = await cdp.eval('window.__ERR');
    if (e) throw new Error('page error: ' + e);
    if (await cdp.eval('window.__READY === true')) break;
    await sleep(100);
  }
  for (const f of frames) {
    const t0 = Date.now();
    const d = await cdp.eval(`(()=>{renderFrame(${f});return document.getElementById('out').toDataURL('image/png')})()`);
    const buf = Buffer.from(d.split(',')[1], 'base64');
    const p = path.join(outDir, `f${String(f).padStart(5, '0')}.png`);
    fs.writeFileSync(p, buf);
    console.log(p, (buf.length / 1024 | 0) + 'KB', (Date.now() - t0) + 'ms');
  }
  cdp.close(); proc.kill('SIGKILL'); srv.close();
  process.exit(0);
})().catch(e => { console.error(e); process.exit(1); });

